{"packet_id":"D067-01","doc_id":"D067","jurisdiction":"NJ","category":"security_deposits","lifecycle":"enacted","title":"New Jersey Security Deposit Law","requirement":"Landlords may not demand a security deposit exceeding 1.5 times one month's rent, may not increase it by more than 10% yearly, must hold it in trust, pay interest to the tenant, and return it within 30 days after tenancy ends.","key_value":"1.5 months' rent; 10% max yearly increase","coverage_conditions":"Residential rental units in New Jersey where a landlord collects a security deposit; seasonal rentals of 125 consecutive days or fewer are exempt from certain provisions.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Residential rentals in NJ; seasonal use ≤125 days exempt"},"exemptions":"Seasonal use or rental for a term of not more than 125 consecutive days for residential purposes by a person having a permanent place of residence elsewhere.","penalty":"Tenant may sue for double the amount wrongfully withheld plus court costs and reasonable attorney's fees; tenant may apply deposit and 7% interest to rent if landlord fails to give required notice or pay interest.","effective_date":null,"citation":"N.J.S.A. 46:8-21.2","quoted_span":"The maximum-security deposit to be collected by the landlord cannot be more than one and one-half times one month’s rent ( N.J.S.A. 46:8-21.2 ). It can be less. Any additional yearly security deposit increase may not exceed 10% of the current security deposit.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D067-01","doc_id":"D067","jurisdiction":"NJ","category":"security_deposits","lifecycle":"enacted","title":"Safe Housing Act security deposit return","requirement":"A tenant terminating a lease under the Safe Housing Act due to domestic violence is entitled to return of the security deposit; the landlord must make it available within 15 business days and notify the tenant within 3 business days of where to collect it.","key_value":"15 business days return; 3 business days notice","coverage_conditions":"Tenants terminating a residential lease under the Safe Housing Act because of domestic violence; does not apply to transient or seasonal rentals.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Domestic violence lease terminations under the Safe Housing Act"},"exemptions":"Transient or seasonal rentals.","penalty":null,"effective_date":null,"citation":"N.J.S.A. 46:8-9.6","quoted_span":"Within 15 business days after the lease  is terminated, the landlord shall make available the return of the tenant’s security deposit, plus any interest earned, to the tenant or the tenant’s agent.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
